const GUIDES=[
{id:'nutrition',title:'מה נכנס לקערה? בונים שגרת תזונה',category:'תזונה',icon:'food',summary:'בחירת מזון, כמויות ושגרה שמתאימה לכלב שלכם.',image:DOGIMAGE,source:SOURCES.nutrition,sourceName:'האגודה האמריקאית למניעת צער בעלי חיים',body:'כמות המזון תלויה בגודל, בגיל, במצב הגוף ובפעילות. התחילו מהנחיות המזון והתאימו עם הווטרינר.\nמדדו מנות, תעדו חטיפים ועקבו אחר משקל ומצב גוף. שינוי בכמות האכילה או במשקל כדאי לתעד ולשתף עם הווטרינר. מים טריים צריכים להיות זמינים.\nמזון רפואי ותוכנית ירידה במשקל דורשים התאמה מקצועית. משקל אופייני לגזע אינו יעד אישי.'},
{id:'training',title:'שפה משותפת מתחילה בחיזוק חיובי',category:'אילוף והתנהגות',icon:'paw',summary:'תרגול קצר, סביבה בטוחה והרבה סבלנות.',image:null,source:SOURCES.training,sourceName:'האגודה הווטרינרית האמריקאית להתנהגות בעלי חיים',body:'לימוד מבוסס תגמול מחזק התנהגות רצויה. בחרו מיומנות אחת, תגמלו מיד כשהכלב מצליח והתקדמו בקצב שלו.\nהתאימו את הסביבה כדי למנוע מצבים קשים מדי. הימנעו מענישה פיזית, הפחדה ואמצעים מכאיבים.\nפחד, תוקפנות או חרדה שמפריעים לשגרה מצריכים איש מקצוע בגישה מבוססת תגמול, ובמידת הצורך הערכה וטרינרית. שינוי התנהגות פתאומי עלול להיות קשור גם לכאב.'},
{id:'routine',title:'הדברים הקטנים ששומרים על הבריאות',category:'בריאות',icon:'heart',summary:'ביקורות, מניעה וטיפוח כחלק מהיום־יום.',image:IMAGE,source:SOURCES.routine,sourceName:'המדריך הווטרינרי מרק',body:'תוכנית בריאות כוללת בדיקות וטרינריות, מניעת טפילים, טיפוח וסביבה בטוחה. תדירות הבדיקות מותאמת לגיל ולמצב הרפואי.\nשימו לב לשינויים בתיאבון, בשתייה, בפעילות, בהליכה ובהפרשות. תעדו מתי התחילו ומה השתנה.\nשמרו תרופות, חומרי ניקוי וחפצים מסוכנים מחוץ להישג הכלב. טיפול מונע ותרופות ניתנים לפי הנחיות הווטרינר והתכשיר בלבד.'},
{id:'vaccine',title:'חיסונים וטיפולים — מסודרים מראש',category:'בריאות',icon:'shield',summary:'לוח טיפולים אישי שנקבע יחד עם הווטרינר.',image:null,source:SOURCES.vaccine,sourceName:'הארגון העולמי לווטרינריה של חיות מחמד',body:'תוכנית חיסונים תלויה בגיל, בהיסטוריה, בסיכון לחשיפה ובהנחיות המקומיות. אין לוח אחד שמתאים לכל כלב.\nהזינו במעקב את שם החיסון או הטיפול, מועד הביצוע ומועד המנה הבאה כפי שנקבע במרפאה.\nהאפליקציה מזכירה את התאריך שהזנתם. היא אינה קובעת תדירות רפואית או משנה תוכנית טיפול.'},
{id:'dental',title:'גם לחיוך שלו מגיעה שגרה',category:'טיפוח',icon:'tooth',summary:'טיפול עדין בשיניים וביקורות לפי הצורך.',image:null,source:SOURCES.dental,sourceName:'המדריך הווטרינרי מרק',body:'צחצוח עקבי מסייע בהפחתת רובד חיידקים. השתמשו במברשת ובמשחה המיועדות לכלבים; אין להשתמש במשחת שיניים של בני אדם.\nהתחילו בהדרגה ובלי כוח. כאב בפה, קושי לאכול, דימום או ריח חריג מצריכים בדיקה.\nצחצוח ביתי אינו מחליף בדיקת שיניים או טיפול מקצועי לפי המלצת הווטרינר.'},
{id:'wound',title:'פצע או סימן בעור: מה מתעדים?',category:'עזרה ראשונית',icon:'med',summary:'תמונה ברורה, פרטים חשובים ופנייה בזמן.',image:null,source:SOURCES.wound,sourceName:'רשת בתי החולים הווטרינריים VCA',body:'צלמו בתאורה טובה ותעדו מיקום, מועד הופעה ושינוי בגודל או בהפרשה. אין להסיק מעומק או מחומרת פצע לפי צילום בלבד.\nפצע פתוח, נשיכה, הפרשה, כאב או החמרה מצריכים ייעוץ וטרינרי. דימום משמעותי או פגיעה עמוקה דורשים פנייה דחופה.\nאל תמרחו משחות, אלכוהול, מי חמצן או חומרי חיטוי בלי הנחיית וטרינר. מנעו ליקוק אם ניתן בבטחה. אל תתנו תרופות של בני אדם.'},
{id:'emergency',title:'מתי עוזבים הכול ופונים לעזרה?',category:'עזרה ראשונית',icon:'activity',summary:'סימני אזהרה שחשוב לזהות ולא להמתין איתם.',image:null,source:SOURCES.emergency,sourceName:'המדריך הווטרינרי מרק',body:'קושי בנשימה, התמוטטות, דימום חמור, פרכוסים מתמשכים, חשד להרעלה או פגיעה משמעותית הם סיבה לפנייה דחופה למרפאה או למיון וטרינרי.\nהתקשרו בדרך, תארו מה קרה ופעלו לפי הנחיות המרפאה. אל תחכו לתשובה של AI.\nשמרו מראש פרטי וטרינר ומרפאת חירום. האפליקציה אינה שירות חירום.'},
{"id": "heat", "title": "חם בחוץ? מטיילים אחרת", "category": "עזרה ראשונית", "icon": "sun", "summary": "מניעת התחממות וסימנים שמצריכים טיפול דחוף.", "source": "https://www.aaha.org/resources/heatstroke-in-pets/", "sourceName": "איגוד בתי החולים האמריקאיים לחיות", "body": "בימים חמים העדיפו שעות קרירות, צל, מים זמינים ופעילות מותאמת. כלבים פחוסי אף, גורים, כלבים מבוגרים ובעלי מחלות רקע עלולים להיות רגישים יותר לחום.\nהתנשפות חריגה, ריור רב, חולשה, חוסר יציבות, הקאות או התמוטטות אחרי חשיפה לחום עלולים להעיד על מכת חום. זהו מצב חירום. העבירו למקום קריר וצרו קשר מיד עם מרפאה וטרינרית לקבלת הנחיות קירור ופינוי.\nאין לחכות לצילום או לתוצאת AI. גם שיפור לכאורה אינו שולל פגיעה פנימית.", "image": null},
{"id": "toxic-food", "title": "מה לא משאירים בהישג הכפה", "category": "בטיחות בבית", "icon": "shield", "summary": "מזונות וחומרים מסוכנים, ומה להכין לשיחה עם המרפאה.", "source": "https://www.fda.gov/animal-veterinary/animal-health-literacy/potentially-dangerous-items-your-pet", "sourceName": "מינהל המזון והתרופות האמריקאי", "body": "שוקולד, קפאין, ענבים וצימוקים, בצל ושום, אלכוהול ומוצרים עם קסיליטול עלולים להזיק לכלבים. גם תרופות של בני אדם, חומרי ניקוי וחפצים שניתן לבלוע חייבים להישמר הרחק מהם.\nקלחי תירס, גלעינים ועצמות עלולים לגרום לחסימה או לפגיעה במערכת העיכול. לא כל סכנה נראית מיד מבחוץ.\nאם יש חשד לבליעה, הרחיקו את החומר ושמרו את האריזה. פנו מיד לווטרינר עם שם החומר, הכמות המשוערת, שעת החשיפה ומשקל הכלב. אל תחכו להופעת סימנים.", "image": null},
{"id": "poison", "title": "חשד להרעלה: פועלים מיד", "category": "עזרה ראשונית", "icon": "med", "summary": "הפרטים שצריך לאסוף והפעולות שלא עושים לבד.", "source": "https://ebusiness.avma.org/files/productdownloads/mcm-client-brochures-pet-first-aid-2023.pdf", "sourceName": "ההסתדרות הווטרינרית האמריקאית", "body": "בחשד למגע או לבליעה של חומר מזיק, התקשרו מיד לווטרינר או למיון וטרינרי. הכינו את גיל הכלב, משקלו, סימנים שנצפו, שם המוצר, הכמות והזמן שחלף. הביאו את האריזה אם אפשר.\nאל תגרמו להקאה ואל תתנו תרופה ללא הוראה מפורשת של וטרינר או מרכז הרעלות וטרינרי. הפעולה המתאימה תלויה בחומר ובמצב הכלב.\nהכוונה ראשונית אינה מחליפה בדיקה. פעלו לפי הנחיות המרפאה לפינוי בטוח.", "image": null},
{"id": "parasites", "title": "טפילים: מניעה שמתאימה לכלב", "category": "בריאות", "icon": "shield", "summary": "פרעושים, קרציות וטפילי מעיים — תוכנית אישית ועקבית.", "source": "https://capcvet.org/guidelines/general-guidelines/", "sourceName": "המועצה למניעת טפילים בחיות מחמד", "body": "תוכנית מניעה צריכה להתחשב באזור המגורים, בטיולים, בגיל, במצב הבריאות ובחשיפה לבעלי חיים אחרים. בדיקות וטיפול מונע נקבעים עם הווטרינר ובהתאם לתכשיר.\nרשמו את שם התכשיר, מועד המתן והמועד הבא שנקבע. אין להחליף מוצר או לשלב תכשירים על דעת עצמכם. הנחיות המקור נכתבו בעיקר לצפון אמריקה; התאמתן לישראל נעשית במרפאה המקומית.\nאספו צואה ושטפו ידיים לאחר מגע. חלק מהטפילים עלולים לעבור גם לאנשים, ולכן היגיינה היא חלק מהמניעה.", "image": null},
{"id": "senior", "title": "הגיל משתנה. תשומת הלב נשארת", "category": "שלבי החיים", "icon": "heart", "summary": "מעקב אחר שינויים בשגרה אצל כלבים מבוגרים.", "source": "https://www.aaha.org/resources/senior-dog-life-stage/", "sourceName": "איגוד בתי החולים האמריקאיים לחיות", "body": "זקנה כשלעצמה אינה מחלה. אצל כלבים מבוגרים חשוב לעקוב אחר ניידות, תיאבון, משקל, שתייה, שינה והתנהגות ולדווח על שינוי למרפאה.\nAAHA ממליצה על בדיקות גופניות לפחות פעמיים בשנה לכלב בשלב החיים המבוגר; תדירות הבדיקות ובדיקות המעבדה מותאמות אישית.\nתעדו מה השתנה ומתי, והביאו את היומן לביקור. ירידה ביכולת לעלות מדרגות או שינוי באופי אינם סיבה להניח שזה ״רק הגיל״.", "image": null},
{"id": "puppy", "title": "גור חדש: להכיר את העולם בקצב שלו", "category": "שלבי החיים", "icon": "paw", "summary": "חשיפה הדרגתית וחיובית, בלי להציף או להפחיד.", "source": "https://avsab.org/socialization-mere-exposure/", "sourceName": "האגודה הווטרינרית האמריקאית להתנהגות בעלי חיים", "body": "חשיפה טובה אינה רק מפגש עם הרבה דברים חדשים. המטרה היא שהגור ירגיש בטוח וילמד בהדרגה להכיר אנשים, קולות וסביבות.\nהתחילו במצבים קלים ותגמלו התנהגות רגועה. אם הגור נרתע, קופא או מנסה להתרחק, הורידו את עוצמת החשיפה ואל תכפו מפגש.\nבחרו חוויות קצרות ומותאמות לאופי שלו. כשיש פחד מתמשך, היעזרו באיש מקצוע בגישה מבוססת תגמול. את מסגרת המפגשים וההגנה ממחלות יש לתאם עם הווטרינר.", "image": null},
{"id": "digestion", "title": "הקאות ושלשול: מה חשוב לרשום", "category": "בריאות", "icon": "activity", "summary": "תדירות, תסמינים נלווים ומתי לפנות לבדיקה.", "source": "https://vcahospitals.com/urgent-care/health-concerns/diarrhea-or-vomiting", "sourceName": "רשת בתי החולים הווטרינריים VCA", "body": "להקאות ולשלשול יכולות להיות סיבות שונות, וחומרתן אינה נקבעת מתמונה. תעדו מתי התחילו, כמה פעמים קרו, שינויים במזון ומצב התיאבון והפעילות.\nהקאות חוזרות, מספר יציאות מימיות, דם בצואה, חוסר תיאבון או אפתיה מצריכים פנייה למרפאה. אם הכלב נראה חולה מאוד או מתקשה לעמוד או ללכת, פנו למיון וטרינרי.\nאין להסתמך על צילום כדי לשלול חסימה או מחלה משמעותית. אל תשנו טיפול קיים בלי להתייעץ.", "image": null},
{"id": "pain", "title": "כאב לא תמיד נשמע כמו בכי", "category": "בריאות", "icon": "heart", "summary": "שינוי בתנועה או בהתנהגות עשוי להיות סימן חשוב.", "source": "https://www.aaha.org/resources/whats-wrong-common-pet-pain-signs/", "sourceName": "איגוד בתי החולים האמריקאיים לחיות", "body": "צליעה, נוקשות בקימה, הימנעות מקפיצה או מדרגות, שינוי בתיאבון, הסתגרות, אי־שקט או ליקוק מוגבר עשויים להיות סימני כאב. הם אינם מאבחנים את הסיבה.\nתעדו מה שונה מההתנהגות הרגילה ומתי התחיל. קבעו בדיקה וטרינרית ואל תענישו כלב על שינוי התנהגות.\nנשימה מאומצת דורשת פנייה מידית. אין להשתמש במשכך כאב של בני אדם על דעת עצמכם.", "image": null},
{"id": "travel", "title": "יוצאים לדרך, עם הכנה קטנה", "category": "בטיחות בבית", "icon": "pin", "summary": "נסיעה בטוחה, פרטי זיהוי וציוד שכדאי לקחת.", "source": "https://www.cdc.gov/healthy-pets/travel/", "sourceName": "המרכז האמריקאי לבקרת מחלות", "body": "לפני נסיעה בדקו שפרטי הקשר המשויכים לשבב מעודכנים. ארגנו מים, מזון, רצועה, שקיות איסוף, תרופות שנרשמו ופרטי המרפאה.\nהרגילו לנסיעות בהדרגה. ברכב השתמשו ברתמה מתאימה המחוברת לחגורה במושב האחורי או במנשא מאובטח ומאוורר בגודל מתאים. אל תאפשרו שוטטות ברכב או הוצאת ראש מהחלון.\nעצרו להפסקות ואל תשאירו כלב לבדו ברכב חונה. בנסיעות לחו״ל בדקו מראש דרישות עדכניות של היעד וחברת התעופה.", "image": null}
];
