const EXTRA_GUIDES=[{"id": "body-language", "title": "מה הוא אומר בלי מילים?", "category": "אילוף והתנהגות", "icon": "eye", "summary": "לומדים לקרוא את הגוף כולו, ולתת מרחב בזמן.", "image": null, "source": "https://www.dogstrust.org.uk/dog-advice/understanding-your-dog/body-language", "sourceName": "ארגון דוגס טראסט לרווחת כלבים", "body": "מסתכלים על התמונה השלמה\nזנב מכשכש אינו הוכחה שהכלב רוצה מגע. התבוננו יחד בגוף, בפנים, באוזניים ובתנועה, ושימו לב למה שקורה סביבו. אותו סימן יכול לבטא דברים שונים בהקשרים שונים.\n\nמזהים בקשה למרחב\nליקוק שפתיים כשאין מזון, הסבת ראש, התרחקות, גוף נוקשה או זנב תחוב עשויים להעיד על אי־נוחות. לא כל כלב מציג את כל הסימנים, ולא תמיד יש אזהרה הדרגתית.\n\nמגיבים מוקדם\nעצרו את המפגש או הפעולה, הגדילו מרחק ואפשרו בחירה. אל תכריחו ליטוף או מפגש כדי ״שיתרגל״. נהמה היא מידע על מצוקה; התגובה היא להתרחק ולנהל את המצב בבטחה.\n\nלומדים את הכלב הפרטי שלכם\nהיכרות עם ההתנהגות הרגילה עוזרת לזהות שינוי. שינוי פתאומי עלול להיות קשור גם לבריאות, ולכן כדאי להתייעץ עם וטרינר כשמופיעה תגובה חדשה או חריגה.", "reviewedAt": "2026-11-06"}, {"id": "enrichment", "title": "האף עובד, הראש נהנה", "category": "אילוף והתנהגות", "icon": "search", "summary": "רעיונות פשוטים למשחקי חיפוש והעשרה בבית.", "image": null, "source": "https://www.dogstrust.org.uk/dog-advice/life-with-your-dog/enrichment/enrichment-activities-for-dogs", "sourceName": "ארגון דוגס טראסט לרווחת כלבים", "body": "יותר מהוצאת אנרגיה\nהעשרה מאפשרת לכלב להשתמש ביכולות טבעיות: להריח, לחפש, ללעוס ולפתור בעיות. המטרה היא חוויה מתאימה ומהנה, לא תחרות או משימה שחייבים להשלים.\n\nמשחק ראשון: מוצאים יחד\nבמקום בטוח ונקי, הניחו מעט מהמזון הרגיל במקומות קלים לראייה ולריח ותנו לכלב לחפש. התחילו בפשטות; כשברור שהוא מבין ונהנה אפשר לגוון את המיקום.\n\nבוחרים ציוד לפי הכלב\nצעצוע האכלה צריך להתאים לגודל, ליכולת ולצרכים התזונתיים. השגיחו בשימוש חדש, והרחיקו פריטים שהכלב קורע ובולע. אין צורך לקנות הרבה ציוד כדי ליצור עניין.\n\nשומרים על הצלחה קטנה\nאם מופיעים תסכול, נטישה או ניסיון לבלוע חלקים, עצרו ושנו את המשחק. שלבו מזון מהמנה היומית במקום להוסיף חטיפים ללא חשבון, וגוונו בין חיפוש, משחק ומנוחה.", "reviewedAt": "2026-11-06"}, {"id": "dog-introductions", "title": "עוד כלב בבית? מכירים בהדרגה", "category": "אילוף והתנהגות", "icon": "dog", "summary": "מכינים סביבה שנותנת לכל כלב מקום משלו.", "image": null, "source": "https://www.battersea.org.uk/pet-advice/dog-advice/introducing-new-dog-existing-dog-family", "sourceName": "ארגון באטרסי לרווחת כלבים וחתולים", "body": "מתכננים לפני המפגש\nפגישה מוצלחת בחוץ אינה מבטיחה שחיים משותפים יהיו פשוטים. הכינו מראש אזורי מנוחה נפרדים, קערות מים במקומות שונים ודרך להפריד בבטחה כשצריך.\n\nמפחיתים תחרות\nבהתחלה האכילו כל כלב בנפרד. צעצועים ופריטי לעיסה עלולים לעורר שמירה על משאבים, ולכן מנהלים את השימוש בהם תחת השגחה ולא משאירים אותם מפוזרים בזמן ההיכרות.\n\nנותנים זמן ומרחב\nאל תדרשו משחק, שינה משותפת או קרבה. לכלב הוותיק מותר לרצות הפסקה מהגור החדש, וגם החדש זקוק לזמן אישי איתכם. שער מתאים עשוי לעזור ליצור הפרדה בהשגחה.\n\nבונים קשר בקצב שלהם\nמפגשים קצרים ורגועים עדיפים על כפיית שהייה ממושכת. אם יש קיפאון, איום או עימות, הפרידו בבטחה ובקשו עזרה מקצועית. אין להכניס ידיים בין כלבים מתקוטטים.", "reviewedAt": "2026-11-06"}, {"id": "separation", "title": "לבד בבית, בלי להרגיש לבד", "category": "אילוף והתנהגות", "icon": "heart", "summary": "מזהים מצוקה בזמן פרידה ובונים תהליך מותאם.", "image": null, "source": "https://www.aspca.org/pet-care/dog-care/common-dog-behavior-issues/separation-anxiety", "sourceName": "האגודה האמריקאית למניעת צער בעלי חיים", "body": "מתבוננים במה שקורה\nנביחות, הרס או צרכים בבית בזמן היעדרות אינם בהכרח ״דווקא״. כשהם מלווים בריור, הליכה חסרת מנוחה או ניסיונות בריחה, ייתכן שהכלב חווה מצוקת פרידה. יש גם סיבות אחרות שצריך לבדוק.\n\nאוספים מידע\nאם אפשר, תעדו בבטחה את הדקות שאחרי היציאה בלי להשאיר את הכלב במצוקה לצורך הניסוי. רשמו מתי הסימנים מתחילים וכמה זמן הוא מסוגל להיות רגוע, ושתפו את הווטרינר.\n\nמתקדמים מתחת לסף המצוקה\nתהליך התנהגותי בנוי מהיעדרויות קצרות ומותאמות, עם חזרה לפני שהכלב נלחץ. הארכת הזמן מהר מדי עלולה להחמיר את הקושי. כשיש מצוקה משמעותית צריך ליווי מקצועי.\n\nבינתיים מנהלים את היום\nהיעזרו באדם מוכר או בסידור מתאים כדי לצמצם מצבי קושי. אין להעניש אחרי החזרה הביתה, ואין להניח שכלוב או צעצוע יפתרו חרדה. טיפול תרופתי, אם נדרש, הוא החלטת וטרינר בלבד.", "reviewedAt": "2026-11-06"}, {"id": "coat-care", "title": "טיפוח הוא זמן של קשר", "category": "טיפוח", "icon": "spark", "summary": "מברשת מתאימה, מגע נעים ותשומת לב לעור ולפרווה.", "image": null, "source": "https://www.aspca.org/pet-care/dog-care/dog-grooming-tips", "sourceName": "האגודה האמריקאית למניעת צער בעלי חיים", "body": "מתאימים את השגרה לפרווה\nתדירות וסוג ההברשה תלויים במבנה הפרווה, באורכה ובנטייה לקשרים. בקשו מהווטרינר או מספר כלבים מקצועי להראות לכם כלי וטכניקה מתאימים; אין לוח אחיד שמתאים לכולם.\n\nמתחילים בעדינות\nבחרו זמן רגוע ותרגלו מפגשים קצרים ונעימים. הברשה עוזרת להסיר שיער מת ולכלוך ולמנוע סבכים. אם מופיעים כאב, ניסיון להתרחק או אי־נוחות, עצרו ואל תמשכו בכוח.\n\nמנצלים את הזמן להתבוננות\nחפשו שינוי בעור, אזורי דלילות, גירוד או טפילים. נשירה יכולה להיות תקינה, אבל קרחות, אדמומיות או נשירה חריגה מצריכות בדיקה. הברשה אינה טיפול במחלת עור.\n\nרחצה וטיפול בקשרים\nבחרו מוצרים המתאימים לכלבים והרחיקו מים וחומרי רחצה מהעיניים ומהאוזניים. קשר צפוף קרוב לעור עדיף להשאיר לאיש מקצוע. אל תגזרו במספריים ליד העור ואל תטפלו בפצע בעצמכם.", "reviewedAt": "2026-11-06"}, {"id": "toilet-training", "title": "יוצאים, מצליחים, מתקדמים", "category": "שלבי החיים", "icon": "check", "summary": "בונים הרגלי ניקיון עם תזמון, תגמול וסבלנות.", "image": null, "source": "https://www.dogstrust.org.uk/dog-advice/training/basics/house-or-toilet-training", "sourceName": "ארגון דוגס טראסט לרווחת כלבים", "body": "נותנים הרבה הזדמנויות\nבהתחלה צאו באופן סדיר, במיוחד אחרי שינה, אכילה, שתייה ומשחק. הישארו קרובים כדי שתוכלו לתגמל מיד אחרי שהכלב מסיים במקום המתאים.\n\nמזהים את הרגע\nרחרוח של הרצפה, סיבובים וחיפוש פינה יכולים להצביע על צורך לצאת. לוו אותו בשקט למקום המתאים ואפשרו לו זמן; היציאה אינה חייבת להפוך מיד למשחק מסיח.\n\nמתגמלים הצלחה, לא מענישים טעות\nשבחו או תנו תגמול קטן מיד אחרי עשיית הצרכים בחוץ. אם קרתה תאונה בבית, נקו היטב ונסו לשפר את התזמון בפעם הבאה. צעקות או ענישה עלולות לגרום לכלב לפחד לעשות צרכים לידכם.\n\nעוקבים בלי לחץ\nגור עשוי להזדקק לחודשים עד להרגל יציב. תיעוד זמני שינה, אוכל ויציאות יכול לעזור לזהות דפוס. שינוי בהרגלים או קושי מתמשך מצריכים שיחה עם וטרינר, ולא הנחה שמדובר רק באילוף.", "reviewedAt": "2026-11-06"}, {"id": "rest-space", "title": "גם לכלב מגיע שקט", "category": "בטיחות בבית", "icon": "clock", "summary": "מקום מנוחה נוח וכלל משפחתי פשוט: כאן לא מפריעים.", "image": null, "source": "https://www.rspca.org.uk/adviceandwelfare/pets/dogs/environment/dogbeds", "sourceName": "האגודה המלכותית למניעת צער בעלי חיים בבריטניה", "body": "מקום שאפשר לבחור בו\nארגנו מיטה נוחה, יבשה ונקייה, הרחק מרוח פרצים וממעבר עמוס. כדאי לאפשר בחירה בין פינה שקטה למקום קרוב למשפחה, במקום להניח שהכלב תמיד רוצה להיות לבד או תמיד במרכז.\n\nמתאימים את המיטה\nודאו שיש מקום לשכב בתנוחות שונות, גם במתיחה מלאה. לכלבים שונים העדפות שונות: חלקם מתכרבלים ואחרים משתרעים. אצל כלב עם כאב או קושי בתנועה שאלו את המרפאה על התאמות.\n\nקובעים כלל לכל הבית\nכשכלב ישן או נח במיטה שלו, לא מלטפים, מושכים או מזמינים אותו למשחק. למדו גם ילדים לכבד את המקום. מנוחה היא צורך, לא פרס שצריך להרוויח.\n\nכשיש כמה כלבים\nדאגו לפחות למיטה נפרדת לכל אחד כדי שלא יצטרכו להתחרות. גם כלבים שמסתדרים היטב צריכים אפשרות לפרטיות. כביסה וניקוי סדירים שומרים על אזור המנוחה נעים לשימוש.", "reviewedAt": "2026-11-06"}, {"id": "vet-visit", "title": "ביקור במרפאה מתחיל בבית", "category": "בריאות", "icon": "med", "summary": "מכינים את הכלב למפגש נעים יותר עם הצוות הווטרינרי.", "image": null, "source": "https://www.aaha.org/resources/preparing-your-pet-for-a-successful-veterinary-visit/", "sourceName": "האיגוד האמריקאי לבתי חולים לבעלי חיים", "body": "מדברים מראש עם המרפאה\nעדכנו אם הכלב חושש מנסיעה, ממגע או מבעלי חיים אחרים. הצוות יכול להציע התאמות להגעה ולהמתנה. שאלו מה להביא ומה מותר לאכול לפני התור; אין להחליט על צום או טיפול מרגיע לבד.\n\nמתרגלים מגע בקצב נוח\nבימים רגועים אפשר לחבר מגע קצר ועדין לתגמול שהכלב אוהב. מתחילים באזור שהוא מקבל בנוחות, מפסיקים אם הוא נסוג, ולא מבצעים בבית בדיקה מכאיבה כדי ״להרגיל״.\n\nלוקחים דברים מוכרים\nצעצוע מתאים או תגמול שאושר לשימוש בביקור יכולים לעזור ליצור חוויה חיובית. אם הצוות מבקש להימנע ממזון לקראת בדיקה, פועלים לפי ההנחיה שלו.\n\nלא מחכים שהפחד יחריף\nקיפאון, ניסיון לברוח, קולות מצוקה או איום הם סיבה לשתף את הווטרינר ולתכנן יחד גישה מתאימה. תרופות לפני ביקור ניתנות רק בהנחיה מקצועית; המטרה היא טיפול בטוח, לא כפייה.", "reviewedAt": "2026-11-06"}, {"id": "exercise", "title": "טיול טוב הוא לא מרוץ", "category": "בריאות", "icon": "activity", "summary": "משלבים תנועה, רחרוח ומשחק שמתאימים לכלב.", "image": null, "source": "https://vcahospitals.com/know-your-pet/dog-behavior-and-training---play-and-exercise", "sourceName": "רשת בתי החולים הווטרינריים וי־סי־איי", "body": "אין מרחק שמתאים לכולם\nיכולת הפעילות תלויה בגיל, בבריאות ובכושר. לפני שמתחילים ריצה או פעילות מאומצת חדשה התייעצו עם וטרינר, והתקדמו בהדרגה. עייפות קיצונית אינה מדד לטיול מוצלח.\n\nמשאירים מקום לאף\nחלק מהטיול יכול להיות בקצב הכלב, עם זמן לחקור ריחות בסביבה בטוחה. זה שונה מתרגול הליכה צמודה, ושתי החוויות יכולות להשתלב בשגרה.\n\nבוחרים משחק שמתאים לאופי\nיש כלבים שמעדיפים משחק עם אדם ואחרים נהנים מצעצוע או מחבואים. התאימו את הקושי והפסיקו לפני שהעוררות עולה למצב שבו קשה להירגע. משחק צריך להישאר נעים ובטוח.\n\nשומרים על מסגרת בטוחה\nהשתמשו ברצועה ובציוד מתאים ליד כביש ובמקומות המחייבים זאת. אל תשחררו כלב שאינו חוזר באופן אמין גם בנוכחות הסחות. בגורים ובכלבים עם מגבלה רפואית התאימו את סוג הפעילות עם המרפאה.", "reviewedAt": "2026-11-06"}, {"id": "food-labels", "title": "מה באמת כתוב על שק המזון?", "category": "תזונה", "icon": "food", "summary": "מבחינים בין מזון מלא, חטיף והבטחה שיווקית.", "image": null, "source": "https://aafco.org/consumers/understanding-pet-food/reading-labels/", "sourceName": "איגוד פקחי המזון לבעלי חיים בארצות הברית", "body": "מתחילים מהייעוד\nעל מזונות המסומנים לפי המסגרת האמריקאית חפשו הצהרה על התאמה תזונתית ושלב החיים. הצהרה על מזון מלא ומאוזן חשובה יותר מהתרשמות מתמונה או משם בולט של מרכיב.\n\nחטיף אינו ארוחה\nמוצרים שנועדו לנשנוש או להאכלה משלימה אינם בהכרח מספקים תזונה מלאה. בדקו אם התווית מציינת שימוש מזדמן או משלים, ואל תהפכו מוצר כזה לבסיס התפריט ללא ייעוץ.\n\nמשווים דברים דומים\nקראו את רשימת המרכיבים, ההוראות ותכולת האריזה, אך אל תסיקו מהן לבדן שהמזון מתאים לכלב עם מחלה או רגישות. התאמה אישית דורשת התייחסות למצב הבריאות, לגיל ולתפריט הכולל.\n\nמכירים את גבולות הסימון\nAAFCO מפרסמת מסגרת תקנים בארצות הברית; זו אינה הבטחה להתאמה לכל כלב או תחליף להנחיות בישראל. במקרה של מזון רפואי או ספק לגבי התווית, פנו לווטרינר עם צילום האריזה המלאה.", "reviewedAt": "2026-11-06"}, {"id": "children-dogs", "title": "חברים טובים, עם גבולות ברורים", "category": "בטיחות בבית", "icon": "shield", "summary": "כללים קטנים שעוזרים לילדים ולכלבים לחיות בנחת.", "image": null, "source": "https://www.rspca.org.uk/adviceandwelfare/pets/dogs/company/children", "sourceName": "האגודה המלכותית למניעת צער בעלי חיים בבריטניה", "body": "השגחה פעילה היא הבסיס\nלא משאירים ילד לבד עם כלב, גם אם זה הכלב המשפחתי שמכירים שנים. מבוגר צריך להיות קרוב, קשוב ומסוגל להתערב; כשאין אפשרות להשגיח מפרידים באופן בטוח.\n\nמלמדים מגע מכבד\nבלי משיכה באוזניים או בזנב, טיפוס על הכלב, חיבוק בכוח או פנים צמודות לפנים. אפשר ללמוד יחד משחק שקט או תרגיל קצר מבוסס תגמול, בהובלת מבוגר.\n\nיש זמנים שבהם נותנים מרחב\nלא ניגשים לכלב בזמן אוכל, לעיסה, שינה, מנוחה או מחלה. לא לוקחים ממנו צעצוע או חטיף. אם הכלב מתרחק, מאפשרים לו ללכת ולא רודפים אחריו.\n\nמכינים פינה שקטה\nמקום מנוחה שהילדים אינם נכנסים אליו מאפשר הפסקה מהמפגש. כשנראה שהילד או הכלב לא נינוחים, עוצרים מוקדם. היכרות טובה אינה סיבה לוותר על כללי בטיחות.", "reviewedAt": "2026-11-06"}, {"id": "loose-lead", "title": "מטיילים יחד, ברצועה רפויה", "category": "אילוף והתנהגות", "icon": "pin", "summary": "תרגול קצר שעוזר להחליף משיכות בשיתוף פעולה.", "image": null, "source": "https://www.dogstrust.org.uk/dog-advice/training/outdoors/walking-nicely-training", "sourceName": "ארגון דוגס טראסט לרווחת כלבים", "body": "מתחילים במקום קל\nבחרו אזור בטוח עם מעט הסחות, וציוד הליכה מתאים ונוח. תרגול ראשון באמצע רחוב עמוס דורש מהכלב הרבה יותר ממה שלמד בבית.\n\nמתגמלים את מה שרוצים\nכשהכלב נמצא לידכם והרצועה רפויה, שבחו ותגמלו. התחילו בכמה צעדים מוצלחים והוסיפו מרחק בהדרגה. המטרה היא ללמד איזו הליכה מאפשרת להמשיך לנוע.\n\nלא מתקדמים בעזרת משיכה\nאם הרצועה נמתחת, עצרו בשקט והמשיכו כשהיא שוב רפויה. הימנעו ממשיכות חדות או ענישה. עקביות בין בני המשפחה עוזרת לכלב להבין את הכלל.\n\nגם רחרוח הוא חלק מהטיול\nשלבו הפסקות לחקירה בטוחה כדי שהיציאה לא תהיה רק תרגיל. אם משיכות קשורות לפחד, התנפלות או קושי מול כלבים אחרים, הגדילו מרחק ופנו לעזרה בגישה מבוססת תגמול.", "reviewedAt": "2026-11-06"}, {"id": "israel-bite", "title": "אדם ננשך או נשרט: למי פונים בישראל?", "category": "עזרה ראשונית", "icon": "med", "summary": "הנחיות משרד הבריאות לאחר חשיפה לבעל חיים.", "image": null, "source": "https://www.gov.il/he/service/treatment_after_animal_bite", "sourceName": "משרד הבריאות בישראל", "body": "המדריך הזה עוסק בפגיעה באדם\nאחרי נשיכה, שריטה או חשיפה חשודה לרוק של בעל חיים יש לפעול לפי הנחיות משרד הבריאות. אין להעתיק הוראות טיפול בפצע של אדם לטיפול בפצע של הכלב.\n\nטיפול מקומי ופנייה להערכה\nשטפו מיד וביסודיות את מקום הפגיעה במים זורמים וסבון, ופנו בהקדם ללשכת הבריאות באזור המגורים כדי לבדוק צורך בטיפול נגד כלבת. פגיעה חמורה מצריכה טיפול רפואי דחוף.\n\nגם כלב מוכר דורש בירור\nלפי משרד הבריאות יש לפנות ללשכת הבריאות גם אם הכלב מוכר וידוע כמחוסן. הכינו את פרטי בעליו, אם קיימים, ומסמכים רפואיים וחיסוניים רלוונטיים. אל תחכו לסימני מחלה.\n\nמחוץ לשעות הפעילות\nבאתר משרד הבריאות מפורט מתי פונים למיון כשהלשכה סגורה ומהם החריגים לפגיעה שטחית מחיית בית מוכרת. כשאין ודאות, בקשו הנחיה רפואית מיידית ולא הערכת סיכון באפליקציה.", "reviewedAt": "2026-11-06"}, {"id": "israel-chip", "title": "מספר אחד שיכול לעזור לחזור הביתה", "category": "בטיחות בבית", "icon": "pin", "summary": "מוודאים שפרטי הקשר במאגר הכלבים הארצי מעודכנים.", "image": null, "source": "https://www.gov.il/he/service/reporting-national-dog-registry", "sourceName": "משרד החקלאות וביטחון המזון בישראל", "body": "הרישום צריך להישאר מעודכן\nהמרכז הארצי לרישום כלבים מחזיק את פרטי הכלבים הרשומים בישראל. בשירות הרשמי אפשר לדווח על בעל חיים שאבד או נמצא, ולעדכן או להוסיף מספר טלפון בהתאם להנחיות.\n\nמה עושים כשמספר הטלפון משתנה?\nפנו לשירות הרשמי ועדכנו את פרטי הקשר. שמירת מספר חדש בכרטיס הכלב באפליקציה אינה מעדכנת את המאגר הממשלתי. אלה שתי מערכות נפרדות.\n\nאם כלב אבד או נמצא\nהשתמשו בערוץ הדיווח של המרכז ופנו גם לשירות הווטרינרי המקומי. שמרו את מספר השבב ומסמכי הרישום במקום נגיש כדי שתוכלו למסור פרטים מדויקים.\n\nבודקים בשירות המקורי\nדרישות זיהוי, מסמכים וערוצי טיפול עשויים להשתנות. קישור המקור מוביל לשירות הממשלה עצמו; אין באפליקציה חיבור אוטומטי למאגר ואין אישור שרישום ממשלתי עודכן.", "reviewedAt": "2026-11-06"}, {"id": "israel-rabies-pet", "title": "הכלב ננשך מחיה חשודה: לא מחכים", "category": "עזרה ראשונית", "icon": "shield", "summary": "מה עושים בישראל בחשד לחשיפת חיית מחמד לכלבת.", "image": null, "source": "https://www.gov.il/he/pages/rabies-faq", "sourceName": "השירותים הווטרינריים במשרד החקלאות בישראל", "body": "פונים מיד לגורם וטרינרי\nאם חיית המחמד ננשכה בידי בעל חיים חשוד או חולה בכלבת, משרד החקלאות מנחה לפנות מיד לווטרינר ולמחלקה הווטרינרית המקומית. לא מחכים לשינוי בהתנהגות או לתוצאת זיהוי מתמונה.\n\nמכינים מידע שימושי\nתעדו את מקום האירוע ומועדו, תיאור של בעל החיים ופרטי החיסונים של הכלב. מסרו את המידע לצוות המטפל ופעלו לפי הנחיותיו להמשך הטיפול והפיקוח.\n\nלא קובעים לבד שאין סכנה\nהמשך הפעולה נקבע בידי הגורמים הווטרינריים בהתאם לנסיבות ולמצב החיסון. אין לשנות חיסון, להחליט על בידוד ביתי או לשחרר בעל חיים חשוד על סמך עצה באינטרנט.\n\nגם אנשים עשויים להזדקק לבדיקה\nאם אדם ננשך, נשרט או נחשף לרוק באופן חשוד, עליו לפנות להערכה לפי הנחיות משרד הבריאות. הטיפול בכלב והבירור לאדם הם מסלולים נפרדים; טיפול באחד אינו מחליף את האחר.", "reviewedAt": "2026-11-06"}];
