async function api(path,data,method){
 const controller=new AbortController();
 const timer=setTimeout(()=>controller.abort(),path==='assistant'?120000:20000);
 try{
  let r;try{r=await fetch('/api/'+path,{method:method||(data?'POST':'GET'),credentials:'same-origin',signal:controller.signal,headers:data?{'Content-Type':'application/json'}:{},...(data?{body:JSON.stringify(data)}:{})});}catch{throw Error(controller.signal.aborted?'השרת לא השיב בזמן. בדקו את החיבור ונסו שוב.':'אין חיבור לשרת. בדקו את החיבור ונסו שוב.');}
  let b;try{b=await r.json();}catch{throw Error(controller.signal.aborted?'השרת לא השיב בזמן. נסו שוב.':'השרת החזיר תשובה לא תקינה.');}
  if(!r.ok){const e=Error(b.error||'אירעה שגיאה.');e.status=r.status;throw e;}return b;
 }finally{clearTimeout(timer);}
}
function validateAuth(values,mode,admin){
 const username=String(values.username||'').normalize('NFKC').trim().toLowerCase();
 if(!/^[\p{L}\p{N}_.-]{3,40}$/u.test(username))return {field:'username',message:'שם המשתמש חייב להכיל 3–40 אותיות או מספרים, ללא רווחים.'};
 if(!values.password)return {field:'password',message:'יש להזין סיסמה כדי להיכנס.'};
 if(values.password.length<10)return {field:'password',message:'הסיסמה חייבת להכיל לפחות 10 תווים. יש להזין סיסמה ארוכה יותר.'};
 if(values.password.length>128)return {field:'password',message:'הסיסמה יכולה להכיל עד 128 תווים.'};
 if(admin&&mode==='register'&&!values.confirmPassword)return {field:'confirmPassword',message:'יש להקליד שוב את הסיסמה בשדה ״אימות סיסמה״.'};
 if(admin&&mode==='register'&&values.password!==values.confirmPassword)return {field:'confirmPassword',message:'הסיסמאות אינן תואמות. יש להקליד את אותה הסיסמה בשני השדות.'};
 return null;
}
