function dogForm(id){const d=state.dogs.find(x=>x.id===id)||{id:'',name:'',breed:'',size:'medium',weight:'',birthday:'',notes:'',vet:'',phone:'',chip:''};openModal(d.id?'הכרטיס של '+d.name:'מכירים את החבר החדש','<form id="dog-form" data-id="'+esc(d.id)+'"><div class="form-grid">'+field('name','שם הכלב',d.name,'required maxlength="60"')+'<label class="form-field">גזע<input name="breed" value="'+esc(d.breed)+'" list="breeds-list" maxlength="100" placeholder="מעורב / לא ידוע"><datalist id="breeds-list">'+BREEDS.map(b=>'<option value="'+b.name+'">').join('')+'</datalist></label>'+field('weight','משקל נוכחי בק״ג',d.weight,'required min="0.1" max="150" step="0.1"','number')+'<label class="form-field">גודל<select name="size">'+options(SIZES,d.size)+'</select></label>'+field('birthday','תאריך לידה, אם ידוע',d.birthday,'max="'+new Date().toISOString().slice(0,10)+'"','date')+field('chip','מספר שבב, אם ידוע',d.chip,'maxlength="50"')+field('vet','שם הווטרינר או המרפאה',d.vet,'maxlength="100"')+field('phone','טלפון המרפאה',d.phone,'maxlength="40"','tel')+'<label class="form-field wide">דברים שכדאי לדעת<textarea name="notes" maxlength="2000" placeholder="אלרגיות, מצב רפואי, הרגלים או הנחיות קיימות">'+esc(d.notes)+'</textarea></label></div><div class="error" id="form-error" role="alert"></div><div class="modal-actions"><button type="submit" class="btn">שמירת הכרטיס '+I('check')+'</button>'+btn('ביטול','close-modal','close','secondary')+'</div></form>');}
