function taskForm(id='',template=''){if(!requireDog())return;const t=state.tasks.find(x=>x.id===id)||{id:'',dogId:selectedDog||state.dogs[0].id,title:'',type:'care',due:new Date(Date.now()+3600000).toISOString(),repeatDays:0,notes:''};if(template==='weight'){t.title='שקילה ותיעוד משקל';t.type='weight';}if(template==='recovery'){t.title='תיעוד החלמה לפי הנחיות המרפאה';t.type='checkup';}if(template==='routine'){t.title='טיפול לפי התוכנית מהווטרינר';t.type='care';}openModal(t.id?'פרטי התזכורת':'מוסיפים תזכורת','<form id="task-form" data-id="'+esc(t.id)+'"><label class="form-field">למי מזכירים?<select name="dogId">'+options(Object.fromEntries(state.dogs.map(d=>[d.id,d.name])),t.dogId)+'</select></label>'+field('title','מה צריך לזכור?',t.title,'required maxlength="120"')+'<div class="form-grid"><label class="form-field">סוג מעקב<select name="type">'+options(TYPES,t.type)+'</select></label>'+field('due','מועד',localDate(t.due),'required','datetime-local')+field('repeatDays','חזרה כל מספר ימים',t.repeatDays,'required min="0" max="730" step="1"','number')+'</div><p class="hint">0 = תזכורת חד־פעמית. טיפול רפואי חוזר רק לפי תדירות שנקבעה במרפאה. תזכורת חוזרת חדשה נוצרת לאחר סימון ביצוע.</p><label class="form-field">הערה / הנחיות מהמרפאה<textarea name="notes" maxlength="1000">'+esc(t.notes)+'</textarea></label><div class="error" id="form-error" role="alert"></div><div class="modal-actions"><button type="submit" class="btn">שמירת התזכורת '+I('check')+'</button>'+(t.id?btn('מחיקת תזכורת','delete-task','trash','danger','data-id="'+esc(t.id)+'"'):'')+'</div></form>');}
