function openArticle(id){const g=GUIDES.find(x=>x.id===id);if(!g)return;openModal(g.title,'<div class="article"><div class="article-meta"><span class="tag">'+g.category+'</span><span>'+readMinutes(g)+' דקות קריאה</span></div>'+g.body.split('\n').filter(Boolean).map(p=>'<p>'+esc(p)+'</p>').join('')+'<div class="article-source">'+I('book')+'<div><strong>על מה המדריך מבוסס?</strong><a class="source-link" href="'+g.source+'" target="_blank" rel="noopener noreferrer">'+g.sourceName+' — פתיחת המקור '+I('arrow')+'</a><small>סיכום מקורי בעברית על בסיס המקור המקושר. המידע אינו מותאם לכלב מסוים ואינו סקירה רפואית של האפליקציה.</small></div></div><p class="hint">מידע כללי בלבד. תוכנית טיפול אישית נקבעת במרפאה.</p><div class="inline-actions"><button type="button" class="btn secondary" data-page="health">'+I('heart')+'ליומן הבריאות</button><button type="button" class="btn secondary" data-page="tracking">'+I('bell')+'למעקבים שלי</button></div></div>');}
