function download(name,text,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function icsEscape(v){return v.replace(/\\/g,'\\\\').replace(/;/g,'\\;').replace(/,/g,'\\,').replace(/\n/g,'\\n');}
function foldLine(s){let result='',line='',bytes=0;const enc=new TextEncoder();for(const c of s){const size=enc.encode(c).length;if(bytes+size>73){result+=line+'\r\n';line=' ';bytes=1;}line+=c;bytes+=size;}return result+line;}
function exportCalendar(){const tasks=[...state.tasks,...birthdayTasks()].filter(t=>!t.done&&(!selectedDog||t.dogId===selectedDog));if(!tasks.length){toast('אין תזכורות פתוחות לייצוא.');return;}const utc=v=>new Date(v).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//FourPaws//Dog Care//HE','CALSCALE:GREGORIAN','METHOD:PUBLISH'];for(const t of tasks){lines.push('BEGIN:VEVENT','UID:'+esc(t.id)+'@pawpath','DTSTAMP:'+utc(Date.now()),'DTSTART:'+utc(t.due),'DTEND:'+utc(Date.parse(t.due)+30*60000),'SUMMARY:'+icsEscape(dogName(t.dogId)+' — '+t.title),'DESCRIPTION:'+icsEscape(t.notes||'תזכורת אישית מ־FourPaws'),...(t.birthday?['RRULE:FREQ=YEARLY;BYMONTH='+t.month+';BYMONTHDAY='+(t.originalLeap?'28,29;BYSETPOS=-1':t.day)]:t.repeatDays?['RRULE:FREQ=DAILY;INTERVAL='+t.repeatDays]:[]),'BEGIN:VALARM','TRIGGER:-PT15M','ACTION:DISPLAY','DESCRIPTION:'+icsEscape(t.title),'END:VALARM','END:VEVENT');}lines.push('END:VCALENDAR');download('fourpaws-reminders.ics',lines.map(foldLine).join('\r\n')+'\r\n','text/calendar;charset=utf-8');toast('קובץ היומן הורד. ייבאו ליומן ואשרו התראות. ייצוא חוזר עלול ליצור כפילויות.');}
async function completeTask(id){const next=structuredClone(state),t=next.tasks.find(x=>x.id===id);if(!t||t.done)return;t.done=true;t.completedAt=new Date().toISOString();const familyTask=next.extras?.family?.find(x=>'family-'+x.id===t.id);if(familyTask)familyTask.done=true;if(t.repeatDays){const due=new Date(t.due);do{due.setDate(due.getDate()+t.repeatDays);}while(due.getTime()<=Date.now());next.tasks.push({...t,id:newId(),done:false,completedAt:'',due:due.toISOString()});}await saveState(next);render();toast('המשימה הושלמה'+(t.repeatDays?' ונוצרה התזכורת הבאה.':'.'));}
